def load_evals(selected=None):
    evals = json.loads((ROOT / "evals.json").read_text())["evals"]
    if not selected:
        return evals
    wanted = set(selected)
    result = [
        item
        for item in evals
        if str(item["id"]) in wanted
        or f"eval-{item['id']}-{item['name']}" in wanted
    ]
    missing = wanted - {str(item["id"]) for item in result} - {
        f"eval-{item['id']}-{item['name']}" for item in result
    }
    if missing:
        raise SystemExit(f"未知 eval: {', '.join(sorted(missing))}")
    return result


def run_root(item, group):
    return RESULTS_ROOT / f"eval-{item['id']}-{item['name']}" / group


def compilation_inputs(item):
    entries = {"page": [], "component": []}
    for relative in item["outputs"]:
        path = Path(relative)
        if path.suffix != ".mpx" or path.as_posix() == "src/app.mpx":
            continue
        entry_type = "page" if "pages" in path.parts else "component"
        entries[entry_type].append(relative)
    return entries


def artifact_inventory(item, root):
    declared = list(item["outputs"])
    missing = [
        relative
        for relative in declared
        if not (root / "outputs" / relative).is_file()
    ]
    compiled = [
        relative
        for values in compilation_inputs(item).values()
        for relative in values
    ]
    support = [relative for relative in declared if relative not in compiled]
    return {
        "declared_files": declared,
        "compiled_mpx_files": compiled,
        "support_files": support,
        "missing_files": missing,
        "all_declared_files_present": not missing,
    }


def dependency_preflight():
    script = "\n".join(
        f"require.resolve({json.dumps(name)})" for name in REQUIRED_PACKAGES
    )
    return subprocess.run(
        ["node", "-e", script],
        cwd=WORKSPACE_ROOT,
        capture_output=True,
        text=True,
    )


